import React, { forwardRef } from "react";
import { Chip, ChipProps } from "@components/chip";

export const MultiSelectChip = forwardRef<HTMLSpanElement, ChipProps>(
  ({ children, ...props }: ChipProps, ref: React.ForwardedRef<HTMLSpanElement>) => {
    return (
      <Chip size="sm" type="outline" variant="neutral" {...props} ref={ref}>
        {children}
      </Chip>
    );
  },
);
MultiSelectChip.displayName = "MultiSelect.Chip";
